import{_ as s,b as n,f as r,I as o}from"./chunks/framework.DYvp_Vyw.js";const h=JSON.parse('{"title":"机器学习期末复习笔记","description":"","frontmatter":{"title":"机器学习期末复习笔记","date":"2025-05-21T01:55:13.000Z","tags":["机器学习"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Machine-Learning-FinalReview.md","filePath":"posts/Machine-Learning-FinalReview.md"}'),a={name:"posts/Machine-Learning-FinalReview.md"};function l(e,t,i,g,p,d){return r(),n("div",null,t[0]||(t[0]=[o(`<p>机器学习的期末复习笔记。(实时更新)<br> 目前更新到第二章！</p><hr><h1 id="第一章-机器学习概述" tabindex="-1">第一章 机器学习概述 <a class="header-anchor" href="#第一章-机器学习概述" aria-label="Permalink to &quot;第一章 机器学习概述&quot;">​</a></h1><blockquote><ol><li>什么是机器学习？<br></li><li>机器学习算法有哪些？<br></li><li>机器学习能够为我们做什么？<br></li></ol></blockquote><h2 id="_1-什么是机器学习" tabindex="-1">1.什么是机器学习？ <a class="header-anchor" href="#_1-什么是机器学习" aria-label="Permalink to &quot;1.什么是机器学习？&quot;">​</a></h2><h3 id="_1-1-机器学习的基本概念" tabindex="-1">1.1 机器学习的基本概念 <a class="header-anchor" href="#_1-1-机器学习的基本概念" aria-label="Permalink to &quot;1.1 机器学习的基本概念&quot;">​</a></h3><ul><li>在很多时候，机器学习被赋予了更广义的名字：<strong>人工智能（AI，Artificial Intelligence）</strong></li><li>计算机是否能够“思考”？</li><li>人工智能的简洁定义：努力将通常由人类完成的智力<strong>任务自动化</strong>。</li><li>AI适合用来解决定义明确的逻辑问题，比如下国际象棋，但它难以给出明确的规则来解决更加复杂、模糊的问题，比如图像分类、语音识别和语言翻译。</li><li>机器学习的概念来自于“计算机器和智能”中提出的一个问题：对于计算机而言，除了“我们命令它做的任何事情”之外，它能否自我学习执行特定任务的方法？计算机能否通过观察数据自动学会数据处理规则？</li><li>新的编程范式：输入的是数据和从这些数据中预期得到的答案，系统输出的是规则，这些规则随后可应用于新的数据，并使计算机自主生成答案。</li><li>机器学习是一种从数据当中发现复杂规律，并<strong>利用规律</strong>对<strong>未来时刻、未知状况</strong>进行<strong>预测和判定</strong>的方法，是当下被认为最有可能实现人工智能的方法。机器学习理论主要是设计和分析一些让计算机可以自动“学习”的算法。</li></ul><blockquote><p>机器学习与人脑学习比较<br> 人脑：总结经验------&gt;发现规律------&gt;预测未来<br> 电脑：训练数据------&gt;建立模型------&gt;预测未知属性<br></p></blockquote><h3 id="_1-2-基本的机器学习术语" tabindex="-1">1.2 基本的机器学习术语 <a class="header-anchor" href="#_1-2-基本的机器学习术语" aria-label="Permalink to &quot;1.2 基本的机器学习术语&quot;">​</a></h3><ul><li><strong>数据集（Dataset）</strong>：数据是进行机器学习的基础，所有数据的集合称为数据集。</li><li><strong>样本（Sample）</strong>：数据集中每条记录是关于一个事件或对象的描述，称为样本。</li><li><strong>属性（Attribute）或特征（Feature）</strong>：每个样本在某方面的表现或性质。</li><li><strong>特征向量（Feature Vector）</strong>：每个样本的特征对应的特征空间中的一个坐标向量。</li><li><strong>学习（Learning）或者训练（Training）</strong>：从数据中学得模型的过程，这个过程通过执行某个学习算法来完成。</li><li><strong>训练数据（Training Data）</strong>：训练过程中使用的数据。</li><li><strong>训练样本（Training Sample）</strong>：训练数据的每个样本。</li><li><strong>训练集</strong>：训练样本组成的集合。</li><li><strong>标签（Label）</strong>：训练数据中可能会指出训练结果的信息。</li><li><strong>测试（Test）</strong>：学习到模型后，使用其进行预测的过程。</li><li><strong>泛化能力（Generalization）</strong>：学习到的模型适用于新样本的能力。机器学习的目标是使得学习到的模型能很好得适用于新样本，而不是仅仅在训练样本上适用。</li></ul><blockquote><p>训练集是训练样本组成的集合。为什么不可以是训练数据组成的集合？<br> 在机器学习中，&quot;训练集&quot;特指<strong>经过严格划分、预处理和标注的专门用于模型训练的结构化样本集合</strong>，它必须与验证集、测试集配套使用，并满足特定的统计特性要求；而&quot;训练数据&quot;是更广义的概念，<strong>泛指所有可用于训练的数据资源，可能包含未处理的原始数据</strong>，不需要配套其他数据集或满足严格的数据规范。学术界更推荐使用&quot;训练集&quot;这一精确术语来指代模型训练阶段使用的结构化数据子集。<br> 而训练样本是<strong>经过预处理和标注的结构化数据实例</strong>，用于机器学习模型的训练。每个训练样本代表一个经过处理的观测数据点。</p></blockquote><table tabindex="0"><thead><tr><th><strong>维度​</strong>​</th><th>​<strong>​训练数据 (Training Data)​</strong>​</th><th>​<strong>​训练样本 (Training Sample)​</strong>​</th></tr></thead><tbody><tr><td>​<strong>​定义​</strong>​</td><td>原始数据集合（未处理）</td><td>经过预处理后的单个数据实例</td></tr><tr><td>​<strong>​形态​</strong>​</td><td>可能是杂乱的非结构化数据</td><td>结构化/标准化的特征向量或矩阵</td></tr><tr><td>​<strong>​用途​</strong>​</td><td>需要清洗和特征工程</td><td>直接输入模型训练</td></tr><tr><td>​<strong>​存储形式​</strong>​</td><td>数据库/CSV/日志文件等</td><td>NumPy数组/Tensor/DataFrame</td></tr></tbody></table><h3 id="_1-3-机器学习的组成" tabindex="-1">1.3 机器学习的组成 <a class="header-anchor" href="#_1-3-机器学习的组成" aria-label="Permalink to &quot;1.3 机器学习的组成&quot;">​</a></h3><ul><li>机器学习中的经验称为模型，机器学习的过程即根据一定的性能度量准则对模型参数进行近似求解，以使得模型在面对新数据时能够给出相应的指导。</li></ul><blockquote><p>机器学习算法要素: 数据、模型、性能度量准则。</p></blockquote><h4 id="_1-3-1-数据" tabindex="-1">1.3.1 数据 <a class="header-anchor" href="#_1-3-1-数据" aria-label="Permalink to &quot;1.3.1 数据&quot;">​</a></h4><ul><li>数据是机器学习算法的原材料，其中蕴含了数据的分布规律。生产实践中直接得到的一线数据往往是“<strong>脏数据</strong>” ，可能包含大量<strong>缺失值、冗余值</strong>，而且不同维度下的数据的量纲往往也不尽相同，需要先期的特征工程对数据进行预处理。</li><li>数据形式：数字化数据、图像数据，语音数据，文本数据等。</li></ul><h4 id="_1-3-2-模型" tabindex="-1">1.3.2 模型 <a class="header-anchor" href="#_1-3-2-模型" aria-label="Permalink to &quot;1.3.2 模型&quot;">​</a></h4><ul><li>如何从众多机器学习模型中选择一个来对数据建模，是一个依赖于数据特点和研究人员经验的问题。常见的机器学习算法主要有<strong>逻辑回归</strong>、<strong>最大熵模型</strong>、<strong>k-近邻算法</strong>、<strong>决策树</strong>、<strong>朴素贝叶斯分类器</strong>、<strong>支持向量机</strong>、<strong>高斯混合模型</strong>、<strong>隐马尔可夫模型</strong>、<strong>降维</strong>、<strong>聚类</strong>、<strong>深度学习</strong>等。</li></ul><blockquote><p>模型和算法的关系？<br> 在机器学习中，​<strong>​算法​</strong>​是用于从数据中学习模式的数学过程或计算步骤（如梯度下降、决策树分裂规则），而​<strong>​模型​</strong>​则是算法运行后生成的具体结果（如训练得到的权重参数或决策树结构）。二者的关系可以类比为：算法是&quot;方法&quot;（如烹饪步骤），模型是&quot;产物&quot;（如做好的菜肴）。选择算法（如SVM、随机森林）决定了模型的学习方式，而最终评估和部署的是训练完成的模型（如SVM的分类超平面、随机森林的树集合）。理解这种&quot;算法生成模型&quot;的层级关系，是正确应用机器学习的关键基础。</p></blockquote><h4 id="_1-3-3-性能度量准则" tabindex="-1">1.3.3 性能度量准则 <a class="header-anchor" href="#_1-3-3-性能度量准则" aria-label="Permalink to &quot;1.3.3 性能度量准则&quot;">​</a></h4><ul><li>性能度量准则<strong>用于指导机器学习模型进行模型参数求解</strong>，这一过程称为<strong>训练</strong>。训练的目的是<strong>使性能度量准则在给定数据集上达到最优</strong>。训练一个机器学习模型往往需要对大量的参数进行<strong>反复调整或者搜索</strong>，这一过程称为<strong>调参</strong>。对于其中在训练之前<strong>调整设置的参数</strong>，称之为<strong>超参数</strong>。</li></ul><h2 id="_2-机器学习算法" tabindex="-1">2.机器学习算法 <a class="header-anchor" href="#_2-机器学习算法" aria-label="Permalink to &quot;2.机器学习算法&quot;">​</a></h2><blockquote><p>按照不同的划分准则，机器学习算法可以分为不同的类型。<br> 1.模型预测输出的连续性：<strong>分类问题</strong>、<strong>回归问题</strong>。<br> 2.是否包含标签及多少：<strong>监督学习</strong>、<strong>半监督学习</strong>、<strong>无监督学习</strong>。<br> 3.是否用于生成新数据：<strong>生成模型</strong>、<strong>判别模型</strong>。<br></p></blockquote><h3 id="_2-1-模型预测输出的连续性" tabindex="-1">2.1 模型预测输出的连续性 <a class="header-anchor" href="#_2-1-模型预测输出的连续性" aria-label="Permalink to &quot;2.1 模型预测输出的连续性&quot;">​</a></h3><h4 id="_2-1-1-分类问题" tabindex="-1">2.1.1 分类问题 <a class="header-anchor" href="#_2-1-1-分类问题" aria-label="Permalink to &quot;2.1.1 分类问题&quot;">​</a></h4><ul><li>根据模型预测输出的连续性，可以将机器学习算法适配的问题划分为<strong>分类问题</strong>和<strong>回归问题</strong>。分类问题以<strong>离散随机变量</strong>或者<strong>离散随机变量的概率分布</strong>作为<strong>预测输出</strong>，回归问题以<strong>连续变量</strong>作为<strong>预测输出</strong>。</li></ul><table tabindex="0"><thead><tr><th><strong>问题类型​</strong>​</th><th>​<strong>​输出形式​</strong>​</th><th>​<strong>​典型场景​</strong>​</th><th>​<strong>​评估指标​</strong>​</th></tr></thead><tbody><tr><td>分类</td><td>离散类别（0/1/A/B/C）</td><td>图像识别、风险评级</td><td>准确率、F1分数</td></tr><tr><td>回归</td><td>连续数值（如3.14）</td><td>房价、温度、销售额预测</td><td>均方误差（MSE）、R²</td></tr></tbody></table><h5 id="_2-1-1-分类问题的概念" tabindex="-1">2.1.1 分类问题的概念 <a class="header-anchor" href="#_2-1-1-分类问题的概念" aria-label="Permalink to &quot;2.1.1 分类问题的概念&quot;">​</a></h5><ul><li><p>用于分类任务的机器学习模型称为<strong>分类模型</strong>或<strong>分类器</strong>。</p></li><li><p>分类任务的目标是通过训练样本构建合适的<strong>分类器𝐶(𝑋)</strong>，完成对目标的分类。</p></li><li><p>分类类别只有两类的分类任务称为<strong>二值分类</strong>或<strong>二分类</strong>，这两个类别分别称为正类和负类，通常用+1和-1分别指代。</p></li><li><p>分类类别多于两类的分类任务通常称之为<strong>多值分类</strong>。</p></li><li><p>分类算法有：<strong>k近邻方法</strong>、<strong>决策树方法</strong>、 <strong>朴素贝叶斯分类方法</strong>等。</p></li><li><p>简单说来，分类所要解决的问题是将一个事件或者对象划分到给定的类别上。例如，斯坦福大学的研究人员已经基于深度学习训练了一种诊断皮肤癌的算法，该算法使用“<strong>130,000张</strong>代表超过2,000种不同疾病的皮病变图像”进行训练，来检测<strong>皮肤癌</strong>或<strong>黑色素瘤</strong>。</p></li></ul><h5 id="_2-1-2-分类问题详细示例" tabindex="-1">2.1.2 分类问题详细示例 <a class="header-anchor" href="#_2-1-2-分类问题详细示例" aria-label="Permalink to &quot;2.1.2 分类问题详细示例&quot;">​</a></h5><p>给定一组数据（训练集），如右图，一条记录都可由一组 (x, y) 来表示, x 代表属性集 ，y 代表类别标号，是经典的鸢尾花数据集示例，包含<strong>4个特征</strong>和<strong>3个类别</strong>：</p><table tabindex="0"><thead><tr><th>花萼长度 (cm)</th><th>花萼宽度 (cm)</th><th>花瓣长度 (cm)</th><th>花瓣宽度 (cm)</th><th>类别标签 (y)</th></tr></thead><tbody><tr><td>5.1</td><td>3.5</td><td>1.4</td><td>0.2</td><td>山鸢尾 (0)</td></tr><tr><td>7.0</td><td>3.2</td><td>4.7</td><td>1.4</td><td>变色鸢尾 (1)</td></tr><tr><td>6.3</td><td>3.3</td><td>6.0</td><td>2.5</td><td>维吉尼亚鸢尾 (2)</td></tr></tbody></table><ul><li><strong>特征 (x)​</strong>​：前4列是数值型特征。</li><li>​<strong>​标签 (y)​</strong>​：最后一列是类别（离散值）。 以Python的<code>scikit-learn</code>库为例：</li></ul><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">from</span><span style="color:#839496;"> sklearn.datasets </span><span style="color:#859900;">import</span><span style="color:#839496;"> load_iris</span></span>
<span class="line"><span style="color:#859900;">from</span><span style="color:#839496;"> sklearn.model_selection </span><span style="color:#859900;">import</span><span style="color:#839496;"> train_test_split</span></span>
<span class="line"><span style="color:#859900;">from</span><span style="color:#839496;"> sklearn.ensemble </span><span style="color:#859900;">import</span><span style="color:#839496;"> RandomForestClassifier</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;"># 加载数据</span></span>
<span class="line"><span style="color:#839496;">data </span><span style="color:#859900;">=</span><span style="color:#839496;"> load_iris()</span></span>
<span class="line"><span style="color:#839496;">X </span><span style="color:#859900;">=</span><span style="color:#839496;"> data.data  </span><span style="color:#586E75;font-style:italic;"># 特征 (x)</span></span>
<span class="line"><span style="color:#839496;">y </span><span style="color:#859900;">=</span><span style="color:#839496;"> data.target  </span><span style="color:#586E75;font-style:italic;"># 标签 (y)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;"># 划分训练集和测试集</span></span>
<span class="line"><span style="color:#839496;">X_train, X_test, y_train, y_test </span><span style="color:#859900;">=</span><span style="color:#839496;"> train_test_split(X, y, test_size</span><span style="color:#859900;">=</span><span style="color:#D33682;">0.3</span><span style="color:#839496;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;"># 训练分类模型（随机森林）</span></span>
<span class="line"><span style="color:#839496;">model </span><span style="color:#859900;">=</span><span style="color:#839496;"> RandomForestClassifier()</span></span>
<span class="line"><span style="color:#839496;">model.fit(X_train, y_train)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;"># 预测新数据</span></span>
<span class="line"><span style="color:#839496;">new_data </span><span style="color:#859900;">=</span><span style="color:#839496;"> [[</span><span style="color:#D33682;">5.0</span><span style="color:#839496;">, </span><span style="color:#D33682;">3.0</span><span style="color:#839496;">, </span><span style="color:#D33682;">1.5</span><span style="color:#839496;">, </span><span style="color:#D33682;">0.2</span><span style="color:#839496;">]]  </span><span style="color:#586E75;font-style:italic;"># 新样本的特征</span></span>
<span class="line"><span style="color:#839496;">predicted_class </span><span style="color:#859900;">=</span><span style="color:#839496;"> model.predict(new_data)  </span><span style="color:#586E75;font-style:italic;"># 输出预测类别</span></span>
<span class="line"><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;预测类别:&quot;</span><span style="color:#839496;">, predicted_class)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h4 id="_2-1-2-回归问题" tabindex="-1">2.1.2 回归问题 <a class="header-anchor" href="#_2-1-2-回归问题" aria-label="Permalink to &quot;2.1.2 回归问题&quot;">​</a></h4><ul><li><p>回归任务是通过若干<strong>带有标注</strong>的样本数据构造出一个预测模型R(X)，使得R(X)的预测输出尽可能符合真实值，并称R(X)为回归模型。使用计算机学习出的模型进行预测得到的是<strong>连续值</strong>。</p></li><li><p>回归模型的典型应用有银行信贷评分、人脸/人体关键点估计、年龄估计、股市预测等。</p></li></ul><h4 id="_2-1-3-分类vs回归" tabindex="-1">2.1.3 分类VS回归 <a class="header-anchor" href="#_2-1-3-分类vs回归" aria-label="Permalink to &quot;2.1.3 分类VS回归&quot;">​</a></h4><h5 id="_2-1-3-1-输出不同" tabindex="-1">2.1.3.1 输出不同 <a class="header-anchor" href="#_2-1-3-1-输出不同" aria-label="Permalink to &quot;2.1.3.1 输出不同&quot;">​</a></h5><ul><li>分类问题输出的是<strong>物体所属的类别</strong>，回归问题输出的是<strong>给定样本的属性值或值区间</strong>。</li><li>分类问题输出的值是<strong>离散</strong>的（有限个类别）、定性的，回归问题输出的值是<strong>连续</strong>的（范围内任意值）、定量的。</li></ul><h5 id="_2-1-3-2-目的不同" tabindex="-1">2.1.3.2 目的不同 <a class="header-anchor" href="#_2-1-3-2-目的不同" aria-label="Permalink to &quot;2.1.3.2 目的不同&quot;">​</a></h5><ul><li><strong>分类的目的</strong>是为得到<strong>决策面</strong>，用于对数据集中的数据进行<strong>分类</strong>。</li><li><strong>回归的目的</strong>是为了得到<strong>最优拟合线</strong>，这个线可以最好<strong>接近数据集中的各个点</strong>。</li></ul><h5 id="_2-1-3-3-结果不同" tabindex="-1">2.1.3.3 结果不同 <a class="header-anchor" href="#_2-1-3-3-结果不同" aria-label="Permalink to &quot;2.1.3.3 结果不同&quot;">​</a></h5><ul><li>分类的结果<strong>没有逼近，最终结果只有一个</strong>。</li><li>回归是对真实值的一种<strong>逼近预测，值是不确定的</strong>。</li></ul><h3 id="_2-2是否包含标签及多少" tabindex="-1">2.2是否包含标签及多少 <a class="header-anchor" href="#_2-2是否包含标签及多少" aria-label="Permalink to &quot;2.2是否包含标签及多少&quot;">​</a></h3><h4 id="_2-2-1-监督学习" tabindex="-1">2.2.1 监督学习 <a class="header-anchor" href="#_2-2-1-监督学习" aria-label="Permalink to &quot;2.2.1 监督学习&quot;">​</a></h4><ul><li>根据样本集合当中是否包含标签以及包含标签的多少，可以将机器学习分为<strong>监督学习</strong>、<strong>半监督学习</strong>和<strong>无监督学习</strong>。</li><li>监督学习是指<strong>样本集合中包含标签</strong>的机器学习。</li><li>基本思想：通过标注值<strong>告诉模型</strong>在<strong>给定输入的情况下应该输出什么值</strong>，由此获得尽可能<strong>接近真实映射方式</strong>的优化模型。即<strong>将预测结果与训练数据的实际结果进行比较</strong>，不断的<strong>调整</strong>预测模型，直到模型的预测结果达到一个预期的<strong>准确率</strong>。</li><li>这种利用<strong>带标注样本</strong>调整模型参数的学习方式，能够<strong>提升模型性能</strong>。</li><li>典型例子：<strong>分类和回归模型</strong>、<strong>决策树</strong>、<strong>贝叶斯模型</strong>、<strong>支持向量机</strong>、<strong>深度学习</strong>。</li></ul><h4 id="_2-2-2-无监督学习" tabindex="-1">2.2.2 无监督学习 <a class="header-anchor" href="#_2-2-2-无监督学习" aria-label="Permalink to &quot;2.2.2 无监督学习&quot;">​</a></h4><ul><li>有标注样本集合的获取往往需要耗费大量的人力、财力。有时也希望从无标注数据中挖掘新的信息，比如电商平台根据用户特征对用户进行归类，以实现商品的精准化推荐。</li><li>基本思想：数据并<strong>不被特别标识</strong>，计算机自行学习<strong>分析</strong>数据内部的<strong>联系、规律、特征</strong>等，进而得出一定的结果（如<strong>内部结构、主要成分</strong>等）。</li><li>训练样本的<strong>类标识是未知的</strong>，要学习的<strong>类集合或数量也可能未知</strong>。</li><li>典型例子：<strong>聚类算法</strong>、<strong>降维算法</strong>是最典型的无监督学习算法。</li></ul><h4 id="_2-2-3-半监督学习" tabindex="-1">2.2.3 半监督学习 <a class="header-anchor" href="#_2-2-3-半监督学习" aria-label="Permalink to &quot;2.2.3 半监督学习&quot;">​</a></h4><ul><li>半监督学习<strong>介于监督学习和非监督学习之间</strong>，输入数据<strong>部分被标识，部分没有被标识</strong>，没标识数据的数量常常<strong>远远大于</strong>有标识数据数量。</li><li>基本思想：<strong>同时</strong>从有标签数据和无标签数据中进行经验学习。这种学习模型可以用来进行预测，但是模型<strong>首先需要学习数据的内在结构</strong>以便合理的组织数据来进行预测。</li><li>典型例子：主要分为<strong>半监督分类</strong>，<strong>半监督回归</strong>，<strong>半监督聚类</strong>和<strong>半监督降维算法</strong>。</li></ul><h4 id="_2-2-4-强化学习" tabindex="-1">2.2.4 强化学习 <a class="header-anchor" href="#_2-2-4-强化学习" aria-label="Permalink to &quot;2.2.4 强化学习&quot;">​</a></h4><ul><li>根据<strong>反馈信息</strong>来<strong>调整机器行为</strong>以<strong>实现自动决策</strong>的一种机器学习方式。</li><li>强化学习主要由<strong>智能体和环境</strong>两个部分组成。智能体是行为的<strong>实施者</strong>，由基于环境信息的<strong>评价函数</strong>对智能体的行为做出评价，若智能体的<strong>行为正确</strong>，则由相应的回报函数<strong>给予</strong>智能体<strong>正向反馈信息以示奖励</strong>，反之则给予智能体<strong>负向反馈</strong>信息<strong>以示惩罚</strong>。</li><li>典型算法：<strong>Q-Learning算法</strong>、<strong>Monte-Carlo Learning算法</strong>。</li></ul><h4 id="_2-2-5-强化学习vs监督学习、无监督学习" tabindex="-1">2.2.5 强化学习vs监督学习、无监督学习 <a class="header-anchor" href="#_2-2-5-强化学习vs监督学习、无监督学习" aria-label="Permalink to &quot;2.2.5 强化学习vs监督学习、无监督学习&quot;">​</a></h4><ul><li>监督学习需要的是标签数据，通过训练获得模型来推断那些不在训练集中的样本的标签应该是什么，监督学习的主要目的是<strong>总结概括</strong>。强化学习需要的是<strong>带有回报的交互数据</strong>，agent需要通过从自己的经验中学习如何使自己的<strong>利益最大化</strong>。</li><li>非监督学习一般是寻找未标注数据中同一类的结构信息，而强化学习专注于为agent实现reward最大化。</li></ul><h3 id="_2-3-是否用于生成新数据" tabindex="-1">2.3 是否用于生成新数据 <a class="header-anchor" href="#_2-3-是否用于生成新数据" aria-label="Permalink to &quot;2.3 是否用于生成新数据&quot;">​</a></h3><h4 id="_2-3-1-生成模型" tabindex="-1">2.3.1 生成模型 <a class="header-anchor" href="#_2-3-1-生成模型" aria-label="Permalink to &quot;2.3.1 生成模型&quot;">​</a></h4><ul><li>生成模型是指通过机器学习算法从<strong>训练集中</strong>学习到<strong>输入和输出的联合概率分布P(X,Y)</strong>。对于新给定的样本，计算x与不同标记之间的<strong>联合分布概率</strong>，选择其中<strong>最大的概率</strong>对应的标签作为<strong>预测输出</strong>。</li><li>典型的生成模型有<strong>朴素贝叶斯分类器</strong>、<strong>高斯混合模型</strong>、<strong>隐马尔可夫模型</strong>、<strong>生成对抗网络</strong>等。</li></ul><h3 id="_2-3-2-判别模型" tabindex="-1">2.3.2 判别模型 <a class="header-anchor" href="#_2-3-2-判别模型" aria-label="Permalink to &quot;2.3.2 判别模型&quot;">​</a></h3><ul><li>判别模型计算的是一个<strong>条件概率分布P(X,Y)</strong>，即<strong>后验概率分布</strong>。</li><li>典型的判别模型有<strong>逻辑回归</strong>、<strong>决策树</strong>、<strong>支持向量机</strong>、<strong>神经网络</strong>、<strong>k-近邻算法</strong>。</li><li>由于生成模型学习的是<strong>样本输入与标签的联合概率分布</strong>，所以可以从生成模型的联合概率分布中进行<strong>采样</strong>，从而生成新的数据，而判别模型只是一个<strong>条件概率分布模型</strong>，<strong>只能</strong>对输入进行<strong>判定</strong>。</li></ul><h2 id="_3-机器学习模型评估" tabindex="-1">3.机器学习模型评估 <a class="header-anchor" href="#_3-机器学习模型评估" aria-label="Permalink to &quot;3.机器学习模型评估&quot;">​</a></h2><h3 id="_3-1-训练和泛化误差" tabindex="-1">3.1 训练和泛化误差 <a class="header-anchor" href="#_3-1-训练和泛化误差" aria-label="Permalink to &quot;3.1 训练和泛化误差&quot;">​</a></h3><ul><li>通常首先将数据划分为<strong>训练集</strong>、<strong>验证集</strong>和<strong>测试集</strong>三个部分。训练集用于对模型的参数进行训练；验证集用于对训练的进行验证挑选、辅助调参；而测试集则用于测试训练好的模型的泛化能力。</li><li>在训练集上，训练过程中使用<strong>训练误差</strong>来<strong>衡量</strong>模型对训练数据的<strong>拟合能力</strong>，在测试集上，则使用泛化误差来测试模型的泛化能力。</li><li>在模型得到充分训练的条件下，训练误差与泛化误差之间的<strong>差异越小</strong>说明模型的<strong>泛化性能越好</strong>，得到一个泛化性能好的模型是机器学习的目的之一。训练误差和测试误差往往选择的是<strong>同一性能度量函数</strong>，只是<strong>作用的数据集不同</strong>。</li></ul><h3 id="_3-2-过拟合和欠拟合" tabindex="-1">3.2 过拟合和欠拟合 <a class="header-anchor" href="#_3-2-过拟合和欠拟合" aria-label="Permalink to &quot;3.2 过拟合和欠拟合&quot;">​</a></h3><table tabindex="0"><thead><tr><th>​<strong>​现象​</strong>​</th><th>​<strong>​训练误差​</strong>​</th><th>​<strong>​测试误差​</strong>​</th><th>​<strong>​模型表现​</strong>​</th></tr></thead><tbody><tr><td>欠拟合</td><td>高</td><td>高</td><td>简单模型（如线性）<strong>无法捕捉规律</strong></td></tr><tr><td>过拟合</td><td>极低</td><td>高</td><td>复杂模型（如高阶多项式）死记硬背</td></tr></tbody></table><ul><li><strong>欠拟合​</strong>​：用一次多项式（直线）拟合，训练集和测试集误差都很高，连曲线趋势都抓不住。</li><li>​<strong>​过拟合​</strong>​：用十五次多项式，训练误差接近零，但测试误差爆炸（如x&gt;10时预测完全失控）</li></ul><blockquote><p>当训练损失较大时，说明模型不能对数据进行很好的拟合，称这种情况为欠拟合；当训练误差小且明显低于泛化误差时，称这种情况为过拟合。此时模型的泛化能力在在较弱。</p></blockquote><hr>`,68)]))}const u=s(a,[["render",l]]);export{h as __pageData,u as default};
